const rowsIn = $json.data.rows;
const rows = rowsIn.map(e => ({ id: e.id, group: e.group, category: e.category,
  expected_decision: e.expected_decision,
  requires_human: Boolean(e.requires_human),
  expected_policy_refs: e.expected_policy_refs || [] }));
return [{ json: { rows } }];

const rows = [];
for (const item of $input.all()) {
  const r = item.json && item.json.data ? item.json.data : null;
  if (r && r.case_id) rows.push(r);
}
if (!rows.length) throw new Error('Brak wynikow do porownania');
rows.sort((a, b) => a.case_id.localeCompare(b.case_id));
return [{ json: { rows } }];

const expRows = $('Build expected map').first().json.rows;
const resRows = $('Parse results').first().json.rows;
const expMap = Object.fromEntries(expRows.map(r => [r.id, r]));
const fresh = {};
let stale = 0;
for (const r of resRows) {
  if (r.decided_at && r.decided_at < $('Report config').first().json.run_started_at) { stale += 1; continue; }
  fresh[r.case_id] = r;
}
const out = [];
for (const e of expRows) {
  const r = fresh[e.id];
  if (!r) {
    out.push({ case_id: e.id, group: e.group, category: e.category,
      expected: e.expected_decision, got: 'MISSING', decision_ok: false,
      human_path_ok: false, confidence: null,
      gate_reason: 'brak swiezego wyniku', evidence_count: 0, policy_refs_ok: false });
    continue;
  }
  const decision_ok = r.final_decision === e.expected_decision;
  const human_ok = r.final_decision === 'TECHNICAL_FAIL' ? false :
    ((r.final_decision === 'HUMAN_REVIEW') === e.requires_human);
  out.push({
    case_id: r.case_id, group: e.group, category: e.category,
    expected: e.expected_decision, got: r.final_decision,
    decision_ok, human_path_ok: human_ok,
    confidence: r.confidence, gate_reason: r.gate_reason,
    evidence_count: Array.isArray(r.evidence) ? r.evidence.length : 0,
    policy_refs_ok: Array.isArray(e.expected_policy_refs) && e.expected_policy_refs.length > 0 &&
      Array.isArray(r.evidence) && e.expected_policy_refs.some(p => r.evidence.includes(p))
  });
}
out.sort((a, b) => a.case_id.localeCompare(b.case_id));
return [{ json: { rows: out, total: out.length, stale_results: stale } }];

const meta = $input.first().json;
const rows = meta.rows;
const total = rows.length;
const okCount = rows.filter(r => r.decision_ok).length;
const humanOkCount = rows.filter(r => r.human_path_ok).length;
const tfCount = rows.filter(r => r.got === 'TECHNICAL_FAIL').length;
const groups = {};
for (const r of rows) {
  if (!groups[r.group]) groups[r.group] = { total: 0, ok: 0 };
  groups[r.group].total += 1;
  if (r.decision_ok) groups[r.group].ok += 1;
}
const mismatches = rows.filter(r => !r.decision_ok).map(r => ({
  case_id: r.case_id, group: r.group, category: r.category,
  expected: r.expected, got: r.got, confidence: r.confidence,
  gate_reason: r.gate_reason
}));
const round1 = x => Math.round(x * 10) / 10;
const cfgC = $('Report config').first().json;
const baseAcc = Number(cfgC.baseline_accuracy);
const warnDrop = Number(cfgC.warn_drop_pct);
const failDrop = Number(cfgC.fail_drop_pct);
const maxTf = Number(cfgC.max_technical_failures);
const accPct = round1((okCount / total) * 100);
let verdict = 'PASS';
let verdict_reasons = [];
if ((baseAcc - accPct) > failDrop) {
  verdict = 'FAIL';
  verdict_reasons.push('accuracy spadla o ' + Math.round((baseAcc - accPct) * 10) / 10 + ' p.p. (> ' + failDrop + ' p.p.)');
} else if ((baseAcc - accPct) > warnDrop) {
  verdict = 'WARNING';
  verdict_reasons.push('accuracy spadla o ' + Math.round((baseAcc - accPct) * 10) / 10 + ' p.p. (> ' + warnDrop + ' p.p.)');
}
if (tfCount > maxTf) {
  verdict = 'FAIL';
  verdict_reasons.push('technical failures: ' + tfCount + ' > ' + maxTf);
}

return [{ json: { report: {
  generated_at: new Date().toISOString(),
  regression_verdict: verdict,
  regression_reasons: verdict_reasons,
  baseline_accuracy_pct: baseAcc,
  total_cases: total,
  decision_accuracy_pct: accPct,
  human_path_accuracy_pct: round1((humanOkCount / total) * 100),
  technical_failures: tfCount,
  stale_results: meta.stale_results || 0,
  per_group: groups,
  mismatches,
  notes: {
    decision_ok_definition: 'final_decision == expected_decision',
    human_path_definition: '(HUMAN_REVIEW == requires_human); TECHNICAL_FAIL nie liczy sie jako ok',
    stale_definition: 'wynik starszy niz Report config.run_started_at'
  }
} } }];

const payload = $json.report !== undefined ? $json.report : $json;
const buf = Buffer.from(JSON.stringify(payload, null, 1), 'utf8');
const bin = await this.helpers.prepareBinaryData(buf, 'eval-report.json', 'application/json');
return [{ json: { filename: 'eval-report.json' }, binary: { data: bin } }];
